"Snowflakes"

@cartocopia 2023-07-29

let for the #WCCChallenge "What’s left behind 🧶"

let is a bit if a two-for the price of one...

let started as a depiction of cutting out paper snowflakes, animating the cuts
with "what's left behind" being the snowflake itself...

(let was intentionally designed to run slowly... so one cut per frame with
 the snowflake unfolding when done...)

let then decided to add a "finish" by eroding the completed image away, showing 
"what's left behind" after it snows is eventually...nothing....

left click restart
right click saves an image


*/

let fr = 15; // desired framerate - keep low enough to see the cutting animation
let flakecount = 10; // desired number of flakes (fill find the closest to fill)

let flakes = [];
let flakeX;
let flakeY;
let flakeS;

function setup() {
	smooth();
	pixelDensity(1);
	frameRate(fr);
	createCanvas(windowWidth, windowHeight);
	background('rgb(112,154,200)');

	// figure out the best fillting number of flakes based on the desired flakecount 
	flakecount = max(2, flakecount);
	let ratio = height / width;
	flakeX = 1;
	flakeY = floor(flakeX * ratio);
	let _wG_1 = 0; while ((flakeX * flakeY <= flakecount) && ++_wG_1 < 20000) {
		flakeX++;
		flakeY = floor(flakeX * ratio);
	}
	flakeX--;
	flakeY = floor(flakeX * ratio);
	flakeS = 0.95*min(width / flakeX, height / flakeY); // scale down to add some space
	restart();
}

function restart() {
	for(let i=flakes.length-1; i>=0; i--) {
		flakes.splice(i,1);
	}
	flakes.push(new flake());
}

function draw() {
	if (flakes.length <= flakeX * flakeY) {
		background('rgb(112,154,200)');
		for (i = 0; i < flakes.length; i++) {
			let x = (i % flakeX + 0.5) * width / flakeX;
			let y = (floor(i / flakeX) + 0.5) * height / flakeY;
			flakes[i].display(x, y, flakeS);
		}
		if (flakes[flakes.length-1].done) { //finished drawing the last flake, start a new one
			flakes.push(new flake());
		}
	} else {
		filter(ERODE);  // melt effect
  }
}



