let lapse = 0; // mouse timer
function mousePressed() {
	if (millis() - lapse > 400) {
		lapse = millis();
		if (mouseButton === RIGHT) {
			save("img_" + nf(year(), 4) + nf(month(), 2) + nf(day(), 2) + '_' + nf(hour(), 2) + nf(minute(), 2) + nf(second(), 2) + ".jpg");
		} else if (mouseButton === LEFT) {
		  restart();
		} else if (mouseButton === CENTER) {}
	}
	return (false)
}

